import{_ as o,o as a,c as t,a0 as n}from"./chunks/framework.CShDTZbC.js";const i="/assets/navigate.DtIFRD09.gif",r="/assets/node-management.3qwXaI42.gif",s="/assets/contextual-menu.033NS7_E.gif",l="/assets/color.DjUDqswZ.gif",d="/assets/tags.DojN7jNf.gif",c="/assets/icons.D7gAbJMm.gif",h="/assets/note.BfVQw0iN.gif",u="/assets/links.rb6gUG2L.gif",q=JSON.parse('{"title":"Features & Navigation Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features.md","filePath":"guide/features.md"}'),g={name:"guide/features.md"};function m(p,e,b,f,k,v){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="features-navigation-guide" tabindex="-1">Features &amp; Navigation Guide <a class="header-anchor" href="#features-navigation-guide" aria-label="Permalink to &quot;Features &amp; Navigation Guide&quot;">​</a></h1><p>This section details every core feature of MindMap Pad, how to navigate the application to access them, and usage instructions.</p><hr><h2 id="_1-infinite-canvas-viewport" tabindex="-1">1. Infinite Canvas &amp; Viewport <a class="header-anchor" href="#_1-infinite-canvas-viewport" aria-label="Permalink to &quot;1. Infinite Canvas &amp; Viewport&quot;">​</a></h2><p>Navigate and explore your workspace freely without spatial boundaries.</p><h3 id="how-to-navigate-use" tabindex="-1">How to Navigate &amp; Use <a class="header-anchor" href="#how-to-navigate-use" aria-label="Permalink to &quot;How to Navigate &amp; Use&quot;">​</a></h3><ul><li><strong>Panning:</strong> Click and drag anywhere on the empty canvas background, or use two-finger trackpad swipe gestures.</li><li><strong>Zooming:</strong> Scroll the mouse wheel up to zoom in and down to zoom out. The view centers smoothly on your cursor pointer.</li><li><strong>Fit to View:</strong> Access map controls from the top menu to re-center and fit all nodes into view.</li></ul><blockquote><p><img src="'+i+'" alt="Canvas Overview Placeholder"></p></blockquote><hr><h2 id="_2-node-management-editing" tabindex="-1">2. Node Management &amp; Editing <a class="header-anchor" href="#_2-node-management-editing" aria-label="Permalink to &quot;2. Node Management &amp; Editing&quot;">​</a></h2><p>Create, organize, and structure your thoughts hierarchically.</p><h3 id="how-to-navigate-use-1" tabindex="-1">How to Navigate &amp; Use <a class="header-anchor" href="#how-to-navigate-use-1" aria-label="Permalink to &quot;How to Navigate &amp; Use&quot;">​</a></h3><ul><li><strong>Adding Nodes:</strong> Press <code>Enter</code> to add a sibling node or <code>Tab</code> to add a child node to the currently selected node.</li><li><strong>Editing Text:</strong> Double-click directly on any node box to enter inline text editing mode. Press <code>Enter</code> to save or <code>Escape</code> to cancel.</li><li><strong>Deleting Nodes:</strong> Select a node and press <code>Delete</code> or <code>Backspace</code>.</li></ul><blockquote><p><img src="'+r+'" alt="Node Management Placeholder"></p></blockquote><hr><h2 id="_3-node-contextual-menu" tabindex="-1">3. Node Contextual Menu <a class="header-anchor" href="#_3-node-contextual-menu" aria-label="Permalink to &quot;3. Node Contextual Menu&quot;">​</a></h2><p>Access quick actions and management tools instantly via right-click interaction on any node.</p><h3 id="how-to-navigate-use-2" tabindex="-1">How to Navigate &amp; Use <a class="header-anchor" href="#how-to-navigate-use-2" aria-label="Permalink to &quot;How to Navigate &amp; Use&quot;">​</a></h3><ul><li><strong>Opening the Menu:</strong> Right-click on any node box on the canvas to open the floating contextual menu.</li><li><strong>Available Actions:</strong> From the contextual menu, you can add child or sibling nodes, delete the node, open styling options, manage tags and icons, or attach notes and external links.</li></ul><blockquote><p><img src="'+s+'" alt="Contextual Menu Placeholder"></p></blockquote><hr><h2 id="_4-color-styling" tabindex="-1">4. Color Styling <a class="header-anchor" href="#_4-color-styling" aria-label="Permalink to &quot;4. Color Styling&quot;">​</a></h2><p>Personalize your mind map nodes with custom background, border, and text colors.</p><h3 id="how-to-navigate-use-3" tabindex="-1">How to Navigate &amp; Use <a class="header-anchor" href="#how-to-navigate-use-3" aria-label="Permalink to &quot;How to Navigate &amp; Use&quot;">​</a></h3><ul><li><strong>Selecting Colors:</strong> Select a node and open the color picker from the toolbar or right-click context menu.</li><li><strong>Customization:</strong> Choose custom background, border, and text colors to visually categorize and highlight important nodes.</li></ul><blockquote><p><img src="'+l+'" alt="Color Styling Placeholder"></p></blockquote><hr><h2 id="_5-tags" tabindex="-1">5. Tags <a class="header-anchor" href="#_5-tags" aria-label="Permalink to &quot;5. Tags&quot;">​</a></h2><p>Categorize and filter your ideas using descriptive tags attached to nodes.</p><h3 id="how-to-navigate-use-4" tabindex="-1">How to Navigate &amp; Use <a class="header-anchor" href="#how-to-navigate-use-4" aria-label="Permalink to &quot;How to Navigate &amp; Use&quot;">​</a></h3><ul><li><strong>Adding Tags:</strong> Open the tag manager from the node&#39;s context menu or properties panel.</li><li><strong>Organization:</strong> Assign multiple tags to nodes to group related concepts across different branches of the mind map.</li></ul><blockquote><p><img src="'+d+'" alt="Tags Placeholder"></p></blockquote><hr><h2 id="_6-icons" tabindex="-1">6. Icons <a class="header-anchor" href="#_6-icons" aria-label="Permalink to &quot;6. Icons&quot;">​</a></h2><p>Enhance visual recognition with emoji or icon indicators on your nodes.</p><h3 id="how-to-navigate-use-5" tabindex="-1">How to Navigate &amp; Use <a class="header-anchor" href="#how-to-navigate-use-5" aria-label="Permalink to &quot;How to Navigate &amp; Use&quot;">​</a></h3><ul><li><strong>Adding Icons:</strong> Select a node and open the icon selector from the context menu.</li><li><strong>Visual Cues:</strong> Attach relevant icons to instantly communicate status, categories, or types of thoughts at a glance.</li></ul><blockquote><p><img src="'+c+'" alt="Icons Placeholder"></p></blockquote><hr><h2 id="_7-notes" tabindex="-1">7. Notes <a class="header-anchor" href="#_7-notes" aria-label="Permalink to &quot;7. Notes&quot;">​</a></h2><p>Attach detailed markdown-formatted notes to any node for expanded context and documentation.</p><h3 id="how-to-navigate-use-6" tabindex="-1">How to Navigate &amp; Use <a class="header-anchor" href="#how-to-navigate-use-6" aria-label="Permalink to &quot;How to Navigate &amp; Use&quot;">​</a></h3><ul><li><strong>Opening Notes:</strong> Click the note badge on any node or open the note editor from the context menu.</li><li><strong>Markdown Support:</strong> Write and format rich markdown notes directly within the built-in modal editor.</li></ul><blockquote><p><img src="'+h+'" alt="Notes Placeholder"></p></blockquote><hr><h2 id="_8-links" tabindex="-1">8. Links <a class="header-anchor" href="#_8-links" aria-label="Permalink to &quot;8. Links&quot;">​</a></h2><p>Connect nodes to external web pages and references for quick access.</p><h3 id="how-to-navigate-use-7" tabindex="-1">How to Navigate &amp; Use <a class="header-anchor" href="#how-to-navigate-use-7" aria-label="Permalink to &quot;How to Navigate &amp; Use&quot;">​</a></h3><ul><li><strong>Adding Links:</strong> Open the link manager or click the link badge on a node to attach an external URL.</li><li><strong>Quick Access:</strong> Click the node link badge or shortcut to navigate directly to the referenced webpage.</li></ul><blockquote><p><img src="'+u+'" alt="Links Placeholder"></p></blockquote><hr><h2 id="_9-history-undo-redo" tabindex="-1">9. History &amp; Undo/Redo <a class="header-anchor" href="#_9-history-undo-redo" aria-label="Permalink to &quot;9. History &amp; Undo/Redo&quot;">​</a></h2><p>Never worry about mistakes with full command history tracking.</p><h3 id="how-to-navigate-use-8" tabindex="-1">How to Navigate &amp; Use <a class="header-anchor" href="#how-to-navigate-use-8" aria-label="Permalink to &quot;How to Navigate &amp; Use&quot;">​</a></h3><ul><li>Use standard keyboard shortcuts (<code>Ctrl+Z</code> / <code>Cmd+Z</code> for Undo, <code>Ctrl+Y</code> / <code>Cmd+Y</code> or <code>Ctrl+Shift+Z</code> / <code>Cmd+Shift+Z</code> for Redo) or access history controls from the main menu.</li></ul><hr><p><a href="/">← Home</a> | <a href="/guide/shortcuts.html">Key Commands →</a></p>',57)])])}const _=o(g,[["render",m]]);export{q as __pageData,_ as default};
